export const DEFAULT_IDS: string[] = ["stick-figure","mobile","browser","server","database","cache","queue","load-balancer","api","cloud","lock","user","postgresql","redis","apachekafka","docker","kubernetes","nginx","aws-lambda","inbox","notification","search-index","bucket","cdn"];

export const norm = (s: string) => s.trim().toLowerCase().replace(/[-_/]+/g, ' ').replace(/\s+/g, ' ');
export function resolveIcon(id: string): IconDef | undefined {
  const n = (id || '').trim().toLowerCase();
  if (!n) return undefined;
  const direct = MAP.get(n) ?? MAP.get(n.replace(/[\s_]+/g, '-'));
  if (direct) return direct;
  const ba = BRAND_ALIAS[n] ?? BRAND_ALIAS[n.replace(/ /g, '')] ?? BRAND_ALIAS[n.replace(/ /g, '-')];
  if (ba) { const b = MAP.get(ba) ?? MAP.get(ba + '-logo'); if (b) return b; }
  const al = ALIAS[n] ?? ALIAS[n.replace(/ /g, '-')] ?? ALIAS[n.replace(/ /g, '')];
  if (al) { const t = MAP.get(al); if (t) return t; }
  const slash = n.split('/').pop() || '';
  if (slash && slash !== n) return MAP.get(slash);
  return undefined;
}
function scoreOne(e: IconDef, n: string): number {
  if (!n) return 0;
  const aid = e.id.replace(/-/g, ' ');
  const aname = e.name.toLowerCase();
  if (aid === n) return 1000;
  if ((ALIAS[n.replace(/ /g, '-')] === e.id) || (ALIAS[n] === e.id)) return 950;
  if (aname === n) return 900;
  if (e.keywords.includes(n)) return 800;
  if (aid.startsWith(n) || aname.startsWith(n)) return 600;
  if (aid.split(' ').some((c) => c.startsWith(n)) || aname.split(' ').some((c) => c.startsWith(n))) return 550;
  if (e.keywords.some((c) => c.startsWith(n))) return 500;
  if (e.keywords.some((c) => c.split(' ').some((o) => o.startsWith(n)))) return 450;
  if (aid.includes(n)) return 100;
  if (e.keywords.some((c) => c.includes(n))) return 50;
  return 0;
}
export function searchIcons(query: string, limit = 60): IconDef[] {
  const n = norm(query);
  if (!n || limit <= 0) return [];
  const parts = n.split(' ').filter(Boolean);
  const scored: { icon: IconDef; score: number; order: number }[] = [];
  ALL.forEach((d, order) => {
    const g = scoreOne(d, n);
    let y = 0, p = 0;
    if (parts.length > 1) for (const m of parts) { const b = scoreOne(d, m); if (b > 0) p++; y += b; }
    const v = parts.length > 1 ? g * 2 + y + (p / parts.length) * 300 : g;
    if (v > 0) scored.push({ icon: d, score: v, order });
  });
  scored.sort((a, b) => b.score - a.score || a.order - b.order);
  const key = BRAND_ALIAS[n.replace(/ /g, '')] ?? BRAND_ALIAS[n] ?? n.replace(/ /g, '');
  const bi = scored.findIndex((d) => d.icon.brand && (d.icon.id === key || d.icon.name.toLowerCase() === n));
  if (bi > 0) { const [b] = scored.splice(bi, 1); scored.unshift(b); }
  return scored.slice(0, limit).map((d) => d.icon);
}
export function defaultIcons(): IconDef[] {
  return DEFAULT_IDS.map((id) => resolveIcon(id)).filter((e): e is IconDef => !!e);
}
const escAttr = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
export function luminance(hex: string): number {
  const n = (i: number) => { const v = parseInt(hex.slice(i, i + 2), 16) / 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * n(0) + 0.7152 * n(2) + 0.0722 * n(4);
}
export function brandFill(e: IconDef, isDark: boolean): string {
  if (!e.brand) return 'currentColor';
  const l = luminance(e.brand.hex);
  if ((isDark && l < 0.06) || (!isDark && l > 0.8)) return 'currentColor';
  return '#' + e.brand.hex;
}
/** Inner SVG markup for a library icon (paths + dot circles, or brand fill). */
export function iconInner(id: string, opts: { brandFill?: string } = {}): string {
  const e = resolveIcon(id);
  if (!e) return '';
  if (e.brand) return e.paths.map((d) => '<path d="' + d + '" fill="' + escAttr(opts.brandFill ?? ('#' + (e.brand as { hex: string }).hex)) + '" stroke="none"/>').join('');
  return e.paths.map((d) => '<path d="' + d + '"/>').join('') + (e.circles ?? []).map((c) => '<circle cx="' + c.cx + '" cy="' + c.cy + '" r="' + c.r + '"/>').join('');
}
export function isBrand(id: string): boolean { return !!resolveIcon(id)?.brand; }

/** Edge-icon geometry, mirroring live `Bs`/`El`: bare glyph straddling the top edge. */
export function edgeIconSize(clean: boolean): number {
  return clean ? 24 : 31;
}

export function edgeIconPos(size: number): { x: number; y: number; gap: number } {
  const gap = Math.round(size * 0.3);
  return { x: Math.round(size * 1.3), y: -size / 2, gap };
}

/** Standalone SVG for an icon (used for icon-only inserts), mirroring live `Jg`. */
export function iconStandalone(id: string, color = '#1c1b19', dark = false, size = 240): string {
  const e = resolveIcon(id);
  if (!e) return '';
  if (e.brand) {
    const fill = brandFill(e, dark);
    return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" aria-hidden="true"><path d="' + e.paths[0] + '" fill="' + escAttr(fill === 'currentColor' ? color : fill) + '" stroke="none"/></svg>';
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none" stroke="' + escAttr(color) + '" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + iconInner(id) + '</svg>';
}

export function iconDataURL(id: string, color = '#1c1b19', dark = false): string | null {
  const svg = iconStandalone(id, color, dark);
  return svg ? 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg) : null;
}
